content.content:
{
  "module": "src/invoiceId.ts",
  "function": "parseInvoiceId",
  "kind": "pure-function",
  "signature": "parseInvoiceId(raw: string): { year: number; month: number; seq: number }",
  "returns": {
    "type": "object",
    "fields": {
      "year": {
        "type": "integer",
        "range": [
          2000,
          2100
        ]
      },
      "month": {
        "type": "integer",
        "range": [
          1,
          12
        ],
        "note": "bez wiodacego zera - \"09\" -> 9"
      },
      "seq": {
        "type": "integer",
        "range": [
          1,
          9999
        ],
        "note": "bez wiodacych zer - \"0042\" -> 42"
      }
    }
  },
  "rules": [
    {
      "id": "INV-R1",
      "rule": "Identyfikator ma postac FV/RRRR/MM/NNNN: staly prefiks \"FV\", rok jako dokladnie 4 cyfry, miesiac jako dokladnie 2 cyfry z zakresu 01-12, numer kolejny jako dokladnie 4 cyfry. Separatorem jest ukosnik.",
      "specSection": "Sekcja 2: Identyfikator faktury / Format",
      "boundaries": [
        {
          "input": {
            "raw": "FV/2026/09/0042"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 9,
            "seq": 42
          },
          "note": "przyklad kanoniczny ze SPEC"
        },
        {
          "input": {
            "raw": "FV/2026/01/0001"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 1,
            "seq": 1
          },
          "note": "dolna granica miesiaca i numeru"
        },
        {
          "input": {
            "raw": "FV/2026/12/9999"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 12,
            "seq": 9999
          },
          "note": "gorna granica miesiaca i numeru"
        },
        {
          "input": {
            "raw": "FV/2026/00/0001"
          },
          "raises": "Error: malformed invoice id",
          "note": "miesiac 00 - ponizej dolnej granicy"
        },
        {
          "input": {
            "raw": "FV/2026/13/0001"
          },
          "raises": "Error: malformed invoice id",
          "note": "miesiac 13 - powyzej gornej granicy"
        },
        {
          "input": {
            "raw": "FV/2026/9/0042"
          },
          "raises": "Error: malformed invoice id",
          "note": "miesiac 1-cyfrowy - `dokladnie dwie cyfry`"
        },
        {
          "input": {
            "raw": "FV/2026/009/0042"
          },
          "raises": "Error: malformed invoice id",
          "note": "miesiac 3-cyfrowy"
        },
        {
          "input": {
            "raw": "FV/2026/09/042"
          },
          "raises": "Error: malformed invoice id",
          "note": "numer 3-cyfrowy - `dokladnie cztery cyfry`"
        },
        {
          "input": {
            "raw": "FV/2026/09/00042"
          },
          "raises": "Error: malformed invoice id",
          "note": "numer 5-cyfrowy"
        },
        {
          "input": {
            "raw": "FV/26/09/0042"
          },
          "raises": "Error: malformed invoice id",
          "note": "rok 2-cyfrowy"
        }
      ]
    },
    {
      "id": "INV-R2",
      "rule": "Biale znaki na poczatku i koncu wartosci sa ignorowane (trim). Biale znaki WEWNATRZ identyfikatora nie sa dopuszczalne.",
      "specSection": "Sekcja 2: Identyfikator faktury / Format",
      "boundaries": [
        {
          "input": {
            "raw": "  FV/2026/09/0042  "
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 9,
            "seq": 42
          },
          "note": "spacje z obu stron"
        },
        {
          "input": {
            "raw": "\tFV/2026/09/0042\n"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 9,
            "seq": 42
          },
          "note": "tab i newline tez sa trimowane"
        },
        {
          "input": {
            "raw": "FV /2026/09/0042"
          },
          "raises": "Error: malformed invoice id",
          "note": "spacja wewnatrz"
        },
        {
          "input": {
            "raw": "FV/2026/09/00 42"
          },
          "raises": "Error: malformed invoice id",
          "note": "spacja wewnatrz numeru"
        },
        {
          "input": {
            "raw": "   "
          },
          "raises": "Error: malformed invoice id",
          "note": "same biale znaki -> po trim pusty string"
        }
      ]
    },
    {
      "id": "INV-R3",
      "rule": "Rok musi lezec w zakresie 2000-2100 wlacznie. Rok skladniowo poprawny (4 cyfry) ale poza zakresem daje RangeError, nie Error.",
      "specSection": "Sekcja 2: Identyfikator faktury / Walidacja",
      "boundaries": [
        {
          "input": {
            "raw": "FV/1999/12/0001"
          },
          "raises": "RangeError: year out of supported range",
          "note": "rok - 1 od dolnej granicy"
        },
        {
          "input": {
            "raw": "FV/2000/01/0001"
          },
          "expectedPerSpec": {
            "year": 2000,
            "month": 1,
            "seq": 1
          },
          "note": "dolna granica wlacznie"
        },
        {
          "input": {
            "raw": "FV/2100/12/9999"
          },
          "expectedPerSpec": {
            "year": 2100,
            "month": 12,
            "seq": 9999
          },
          "note": "gorna granica wlacznie"
        },
        {
          "input": {
            "raw": "FV/2101/01/0001"
          },
          "raises": "RangeError: year out of supported range",
          "note": "rok + 1 od gornej granicy"
        },
        {
          "input": {
            "raw": "FV/0000/01/0001"
          },
          "raises": "RangeError: year out of supported range",
          "note": "skrajnie niski rok 4-cyfrowy"
        },
        {
          "input": {
            "raw": "FV/9999/12/9999"
          },
          "raises": "RangeError: year out of supported range",
          "note": "skrajnie wysoki rok 4-cyfrowy"
        }
      ]
    },
    {
      "id": "INV-R4",
      "rule": "Numer kolejny rowny 0000 jest niedopuszczalny (RangeError). Najmniejszy dopuszczalny numer to 0001.",
      "specSection": "Sekcja 2: Identyfikator faktury / Walidacja",
      "boundaries": [
        {
          "input": {
            "raw": "FV/2026/09/0000"
          },
          "raises": "RangeError: sequence number must not be zero"
        },
        {
          "input": {
            "raw": "FV/2026/09/0001"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 9,
            "seq": 1
          },
          "note": "pierwsza dopuszczalna wartosc"
        }
      ]
    },
    {
      "id": "INV-R5",
      "rule": "Wynik zwraca year, month i seq jako liczby calkowite bez wiodacych zer (parsowanie dziesietne, nie oktalne).",
      "specSection": "Sekcja 2: Identyfikator faktury / Wynik",
      "boundaries": [
        {
          "input": {
            "raw": "FV/2026/09/0042"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 9,
            "seq": 42
          },
          "note": "\"09\" -> 9 (nie 0o9 / NaN), \"0042\" -> 42"
        },
        {
          "input": {
            "raw": "FV/2026/08/0008"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 8,
            "seq": 8
          },
          "note": "\"08\" i \"0008\" - cyfry, ktore w notacji oktalnej byly by bledne"
        },
        {
          "input": {
            "raw": "FV/2026/10/0100"
          },
          "expectedPerSpec": {
            "year": 2026,
            "month": 10,
            "seq": 100
          },
          "note": "zero w srodku liczby"
        }
      ],
      "invariant": "Number.isInteger(r.year) && Number.isInteger(r.month) && Number.isInteger(r.seq)"
    }
  ],
  "inputDomains": {
    "raw": {
      "type": "string",
      "hasRequiredTextFormat": true,
      "pattern": "^\\s*FV/(\\d{4})/(0[1-9]|1[0-2])/(\\d{4})\\s*$",
      "patternNote": "Wzorzec obejmuje trim. Sam kod dopasowuje `^FV\\/(\\d{4})\\/(0[1-9]|1[0-2])\\/(\\d{4})$` do `raw.trim()` (src/invoiceId.ts:16). Dopasowanie wzorca to warunek KONIECZNY, nie wystarczajacy - po nim jeszcze obowiazuja INV-R3 (rok 2000-2100) i INV-R4 (numer != 0000).",
      "patternFullyValid": "^\\s*FV/(20(0\\d|[1-9]\\d)|2100)/(0[1-9]|1[0-2])/(?!0000)(\\d{4})\\s*$",
      "patternFullyValidNote": "Wzorzec wartosci, ktore przechodza CALA walidacje (format + zakres roku + niezerowy numer) - tego wzorca powinien uzyc generator do produkcji wejsc pozytywnych.",
      "digitsNote": "`\\d` w tym wyrazeniu jest ASCII-only (brak flagi `u`), wiec cyfry innych systemow pisma (np. arabsko-indyjskie \"٢٠٢٦\") NIE pasuja i daja `Error: malformed invoice id`.",
      "caseSensitive": true,
      "validExamples": [
        "FV/2026/09/0042",
        "FV/2000/01/0001",
        "FV/2100/12/9999",
        "  FV/2026/09/0042  ",
        "FV/2026/08/0008",
        "FV/2050/10/0100",
        "\tFV/2099/11/1234\n"
      ],
      "invalidExamples": [
        {
          "value": "fv/2026/09/0042",
          "reason": "prefiks malymi literami - prefiks \"FV\" jest staly i case-sensitive",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV-2026-09-0042",
          "reason": "myslnik zamiast ukosnika",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV/2026/09/0042/1",
          "reason": "nadmiarowy segment na koncu",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV/2026/9/0042",
          "reason": "miesiac jednocyfrowy",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV/2026/13/0001",
          "reason": "miesiac poza 01-12",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV/2026/09/042",
          "reason": "numer trzycyfrowy",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "",
          "reason": "pusty string",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV/2026/09/00A2",
          "reason": "litera w numerze kolejnym",
          "raises": "Error: malformed invoice id"
        },
        {
          "value": "FV/1999/12/0001",
          "reason": "format poprawny, rok ponizej 2000",
          "raises": "RangeError: year out of supported range"
        },
        {
          "value": "FV/2101/01/0001",
          "reason": "format poprawny, rok powyzej 2100",
          "raises": "RangeError: year out of supported range"
        },
        {
          "value": "FV/2026/09/0000",
          "reason": "format poprawny, numer kolejny zerowy",
          "raises": "RangeError: sequence number must not be zero"
        }
      ],
      "nonStringProbes@expr": [
        "null",
        "undefined",
        "42",
        "{}",
        "[]",
        "true",
        "Symbol('FV/2026/09/0042')"
      ],
      "nonStringProbesRaises": "TypeError: invoice id must be a string"
    }
  },
  "errors": [
    {
      "type": "TypeError",
      "message": "invoice id must be a string",
      "condition": "typeof raw !== \"string\"",
      "specSection": "Sekcja 2 / Walidacja",
      "triggers@expr": [
        "null",
        "undefined",
        "42",
        "{}",
        "['FV/2026/09/0042']",
        "new String('FV/2026/09/0042')"
      ],
      "precedence": 1,
      "note": "Obiekt `new String(...)` ma typeof \"object\", wiec tez daje TypeError, mimo ze `.trim()` by zadzialal."
    },
    {
      "type": "Error",
      "message": "malformed invoice id",
      "condition": "raw.trim() nie pasuje do wzorca formatu",
      "specSection": "Sekcja 2 / Walidacja",
      "triggers": [
        "",
        "   ",
        "FV/2026/9/0042",
        "FV/2026/13/0001",
        "fv/2026/09/0042",
        "FV-2026-09-0042",
        "FV/2026/09/00A2"
      ],
      "precedence": 2
    },
    {
      "type": "RangeError",
      "message": "year out of supported range",
      "condition": "year < 2000 || year > 2100 (sprawdzane dopiero po dopasowaniu formatu)",
      "specSection": "Sekcja 2 / Walidacja",
      "triggers": [
        "FV/1999/12/0001",
        "FV/2101/01/0001",
        "FV/0000/01/0001",
        "FV/9999/12/9999"
      ],
      "precedence": 3
    },
    {
      "type": "RangeError",
      "message": "sequence number must not be zero",
      "condition": "seq === 0 (sprawdzane dopiero po dopasowaniu formatu i walidacji roku)",
      "specSection": "Sekcja 2 / Walidacja",
      "triggers": [
        "FV/2026/09/0000",
        "FV/2000/01/0000"
      ],
      "precedence": 4
