{
  "module": "src/pricing.ts",
  "function": "calculateShipping",
  "kind": "pure-function",
  "signature": "calculateShipping(weightKg: number, zone: string, isPremium: boolean): number",
  "returns": {
    "type": "number",
    "unit": "PLN",
    "constraint": "kwota nieujemna, zaokraglona do 2 miejsc po przecinku (Math.round(x*100)/100)",
    "minObservable": 9.6,
    "maxObservable": 119
  },
  "rules": [
    {
      "id": "SHIP-R1",
      "rule": "Stawka bazowa zalezy od strefy: \"PL\" = 12.00 PLN, \"EU\" = 29.00 PLN, dowolna inna wartosc = 79.00 PLN.",
      "specSection": "Sekcja 1: Koszt dostawy / Stawka bazowa wedlug strefy",
      "boundaries": [
        {
          "input": {
            "weightKg": 1,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 12,
          "note": "dokladne dopasowanie \"PL\""
        },
        {
          "input": {
            "weightKg": 1,
            "zone": "EU",
            "isPremium": false
          },
          "expectedPerSpec": 29,
          "note": "dokladne dopasowanie \"EU\""
        },
        {
          "input": {
            "weightKg": 1,
            "zone": "WORLD",
            "isPremium": false
          },
          "expectedPerSpec": 79,
          "note": "galaz domyslna"
        },
        {
          "input": {
            "weightKg": 1,
            "zone": "pl",
            "isPremium": false
          },
          "expectedPerSpec": 79,
          "note": "porownanie jest case-sensitive - \"pl\" wpada w galaz domyslna"
        },
        {
          "input": {
            "weightKg": 1,
            "zone": "PL ",
            "isPremium": false
          },
          "expectedPerSpec": 79,
          "note": "brak trim() - spacja konczaca lamie dopasowanie"
        },
        {
          "input": {
            "weightKg": 1,
            "zone": "",
            "isPremium": false
          },
          "expectedPerSpec": 79,
          "note": "pusty string to legalne wejscie, nie blad"
        }
      ]
    },
    {
      "id": "SHIP-R2",
      "rule": "Doplata wagowa naliczana jednorazowo do stawki bazowej: waga > 30 kg daje +40.00 PLN, waga > 10 kg i <= 30 kg daje +15.00 PLN, waga <= 10 kg nie daje doplaty. Progi sa scisle (>) - wartosc rowna progowi nalezy do nizszego przedzialu.",
      "specSection": "Sekcja 1: Koszt dostawy / Doplata wagowa",
      "boundaries": [
        {
          "input": {
            "weightKg": 10,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 12,
          "note": "10 kg wlacznie - brak doplaty (dolna strona progu 10)"
        },
        {
          "input": {
            "weightKg": 10.0001,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 27,
          "note": "pierwsza wartosc powyzej 10 - doplata +15"
        },
        {
          "input": {
            "weightKg": 30,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 27,
          "note": "30 kg wlacznie - nadal +15 (dolna strona progu 30)"
        },
        {
          "input": {
            "weightKg": 30.0001,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 52,
          "note": "pierwsza wartosc powyzej 30 - doplata +40, nie +55 (doplaty sie nie kumuluja)"
        },
        {
          "input": {
            "weightKg": 100,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 52,
          "note": "gorna dopuszczalna waga"
        }
      ]
    },
    {
      "id": "SHIP-R3",
      "rule": "Klient premium (isPremium === true) placi 80% kwoty wyliczonej po stawce bazowej i doplacie wagowej.",
      "specSection": "Sekcja 1: Koszt dostawy / Rabat premium",
      "boundaries": [
        {
          "input": {
            "weightKg": 1,
            "zone": "PL",
            "isPremium": true
          },
          "expectedPerSpec": 9.6,
          "note": "12 * 0.8"
        },
        {
          "input": {
            "weightKg": 1,
            "zone": "PL",
            "isPremium": false
          },
          "expectedPerSpec": 12,
          "note": "przelacznik false"
        },
        {
          "input": {
            "weightKg": 20,
            "zone": "EU",
            "isPremium": true
          },
          "expectedPerSpec": 35.2,
          "note": "(29 + 15) * 0.8"
        },
        {
          "input": {
            "weightKg": 100,
            "zone": "WORLD",
            "isPremium": true
          },
          "expectedPerSpec": 95.2,
          "note": "(79 + 40) * 0.8 - maksymalny rabat premium"
        },
        {
          "input": {
            "weightKg": 30.0001,
            "zone": "PL",
            "isPremium": true
          },
          "expectedPerSpec": 41.6,
          "note": "(12 + 40) * 0.8 - rabat po doplacie, nie przed"
        }
      ]
    },
    {
      "id": "SHIP-R4",
      "rule": "Wynik jest kwota w zlotych zaokraglona do dwoch miejsc po przecinku.",
      "specSection": "Sekcja 1: Koszt dostawy / Wynik",
      "boundaries": [
        {
          "input": {
            "weightKg": 10.5,
            "zone": "PL",
            "isPremium": true
          },
          "expectedPerSpec": 21.6,
          "note": "27 * 0.8 - mnozenie float musi zostac dociete do 2 miejsc"
        },
        {
          "input": {
            "weightKg": 31,
            "zone": "EU",
            "isPremium": true
          },
          "expectedPerSpec": 55.2,
          "note": "69 * 0.8"
        }
      ],
      "invariant": "Math.abs(result * 100 - Math.round(result * 100)) < 1e-9"
    }
  ],
  "inputDomains": {
    "weightKg": {
      "type": "number",
      "hasRequiredTextFormat": false,
      "allowedRange": {
        "min": 0,
        "minInclusive": false,
        "max": 100,
        "maxInclusive": true
      },
      "description": "Waga w kilogramach. Skonczona liczba z przedzialu (0, 100]. Nie musi byc calkowita.",
      "equivalenceClasses": [
        {
          "name": "nie-liczba-skonczona",
          "valid": false,
          "probes@expr": [
            "NaN",
            "Infinity",
            "-Infinity"
          ],
          "raises": "TypeError"
        },
        {
          "name": "zero-lub-ujemna",
          "valid": false,
          "probes": [
            0,
            -0.01,
            -1,
            -100
          ],
          "probes@expr": [
            "-0"
          ],
          "raises": "RangeError",
          "note": "-0 <= 0 jest prawdziwe, wiec -0 tez jest odrzucone"
        },
        {
          "name": "lekka",
          "valid": true,
          "probes": [
            0.01,
            1,
            5,
            9.99,
            10
          ],
          "probes@expr": [
            "Number.MIN_VALUE"
          ]
        },
        {
          "name": "srednia",
          "valid": true,
          "probes": [
            10.0001,
            10.5,
            15,
            29.99,
            30
          ]
        },
        {
          "name": "ciezka",
          "valid": true,
          "probes": [
            30.0001,
            50,
            99.99,
            100
          ]
        },
        {
          "name": "ponad-limit",
          "valid": false,
          "probes": [
            100.0001,
            101,
            1000
          ],
          "raises": "RangeError"
        }
      ],
      "boundaryValues": [
        0,
        0.01,
        10,
        10.0001,
        30,
        30.0001,
        100,
        100.0001
