  "module": "src/loyalty.ts",
  "function": "awardPoints",
  "kind": "pure-function",
  "signature": "awardPoints(orderValuePLN: number, lifetimeSpendPLN: number): number",
  "returns": {
    "type": "integer",
    "unit": "punkty lojalnosciowe",
    "range": [
      0,
      5000
    ],
    "invariant": "Number.isInteger(result) && result >= 0 && result <= 5000"
  },
  "rules": [
    {
      "id": "LOY-R1",
      "rule": "Klient otrzymuje 1 punkt za kazde 10 zlotych wartosci zamowienia: punkty = round_half_to_even(orderValuePLN / 10). Zaokraglenie jest BANKIERSKIE - do najblizszej liczby calkowitej, a przy dokladnej polowie do liczby PARZYSTEJ.",
      "specSection": "Sekcja 3: Punkty lojalnosciowe / Przelicznik",
      "boundaries": [
        {
          "input": {
            "orderValuePLN": 0,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 0,
          "currentCodeBehavior": 0,
          "note": "dolna granica domeny"
        },
        {
          "input": {
            "orderValuePLN": 4.9,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 0,
          "currentCodeBehavior": 0,
          "note": "0.49 -> 0"
        },
        {
          "input": {
            "orderValuePLN": 5,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 0,
          "currentCodeBehavior": 0,
          "note": "0.5 -> 0 bo 0 jest parzyste (bankierskie); half-up dalby 1"
        },
        {
          "input": {
            "orderValuePLN": 9.99,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 1,
          "currentCodeBehavior": 0,
          "note": "0.999 -> 1; ROZBIEZNOSC: kod uzywa Math.floor"
        },
        {
          "input": {
            "orderValuePLN": 15,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 2,
          "currentCodeBehavior": 1,
          "note": "1.5 -> 2 (parzyste); ROZBIEZNOSC"
        },
        {
          "input": {
            "orderValuePLN": 24,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 2,
          "currentCodeBehavior": 2,
          "note": "2.4 -> 2 (przyklad ze SPEC)"
        },
        {
          "input": {
            "orderValuePLN": 25,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 2,
          "currentCodeBehavior": 2,
          "note": "2.5 -> 2 (przyklad ze SPEC, parzyste)"
        },
        {
          "input": {
            "orderValuePLN": 26,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 3,
          "currentCodeBehavior": 2,
          "note": "2.6 -> 3 (przyklad ze SPEC); ROZBIEZNOSC"
        },
        {
          "input": {
            "orderValuePLN": 35,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 4,
          "currentCodeBehavior": 3,
          "note": "3.5 -> 4 (przyklad ze SPEC, parzyste); ROZBIEZNOSC - to najostrzejszy test bankierskiego zaokraglenia"
        },
        {
          "input": {
            "orderValuePLN": 45,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 4,
          "currentCodeBehavior": 4,
          "note": "4.5 -> 4 (parzyste); half-up dalby 5"
        },
        {
          "input": {
            "orderValuePLN": 10,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 1,
          "currentCodeBehavior": 1,
          "note": "dokladna wielokrotnosc 10"
        }
      ],
      "roundingMode": "half-to-even (banker's rounding)",
      "roundingTieProbes": [
        5,
        15,
        25,
        35,
        45,
        55,
        105,
        115
      ],
      "roundingTieExpectedPerSpec": [
        0,
        2,
        2,
        4,
        4,
        6,
        10,
        12
      ]
    },
