          "note": "nowy klient"
        }
      ]
    },
    {
      "id": "LOY-R3",
      "rule": "Za jedno zamowienie mozna otrzymac maksymalnie 5000 punktow. Limit stosuje sie PO naliczeniu mnoznika VIP (nie przed).",
