        },
        {
          "input": {
            "orderValuePLN": 50000,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 5000,
          "currentCodeBehavior": 5000,
          "note": "DOKLADNIE na limicie - nie obcinane (warunek to `points > 5000`)"
        },
        {
          "input": {
            "orderValuePLN": 50010,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 5000,
          "currentCodeBehavior": 5000,
          "note": "5001 -> obciete do 5000"
        },
        {
          "input": {
            "orderValuePLN": 1E+9,
            "lifetimeSpendPLN": 0
          },
          "expectedPerSpec": 5000,
          "currentCodeBehavior": 5000,
          "note": "skrajnie duza kwota - limit trzyma"
        },
        {
          "input": {
            "orderValuePLN": 25000,
            "lifetimeSpendPLN": 6000
          },
          "expectedPerSpec": 5000,
          "currentCodeBehavior": 5000,
