        },
        {
          "input": {
            "orderValuePLN": 25010,
            "lifetimeSpendPLN": 6000
          },
          "expectedPerSpec": 5000,
          "currentCodeBehavior": 5000,
          "note": "2501 * 2 = 5002 -> obciete"
        },
        {
          "input": {
            "orderValuePLN": 30000,
            "lifetimeSpendPLN": 6000
          },
          "expectedPerSpec": 5000,
          "currentCodeBehavior": 5000,
          "note": "3000 punktow bazowo (pod limitem), 6000 po VIP -> obciete. Test kolejnosci: limit PO mnozniku, nie przed - przy odwrotnej kolejnosci wynik bylby 6000."
        },
        {
          "input": {
            "orderValuePLN": 40000,
            "lifetimeSpendPLN": 4999.99
          },
          "expectedPerSpec": 4000,
          "currentCodeBehavior": 4000,
          "note": "kontrola do poprzedniego: bez VIP ta sama kwota nie dobija do limitu"
        }
      ],
      "capBoundaryInPointsSpace": {
        "notClamped": 5000,
        "clamped": 5001
      }
    }
  ],
