{
  "f": "Cart.add",
  "inputDomains": {
    "sku": {
      "type": "string",
      "hasRequiredTextFormat": false,
      "formatNote": "SPEC nie definiuje zadnego formatu SKU ani nie przewiduje bledu dla SKU - `add` nie waliduje tego parametru w ogole. SKU jest wylacznie kluczem tozsamosci pozycji, porownywanym przez `===` (src/cart.ts:28). Dlatego nie podaje sie tu wzorca ani przykladow niepoprawnych - kazdy string jest poprawny.",
      "allowedRange": "dowolny string",
      "identityRole": "klucz laczacy wywolania add/remove w sekwencji - patrz statefulSequences.sharedArguments",
      "representativeValues": [
        "SKU-1",
        "SKU-2",
        "ABC-123",
        "a",
        "",
        "sku-1",
        "SKU 1",
        "SKU/1",
        "🛒"
      ],
      "collisionProbePairs": [
        {
          "a": "SKU-1",
          "b": "SKU-1",
          "sameLine": true
        },
        {
          "a": "SKU-1",
          "b": "sku-1",
          "sameLine": false,
          "note": "rozna wielkosc liter"
        },
        {
          "a": "SKU-1",
          "b": "SKU-1 ",
          "sameLine": false,
          "note": "brak trim - spacja konczaca tworzy nowa pozycje"
        },
        {
          "a": "",
          "b": "",
          "sameLine": true,
          "note": "pusty SKU jest legalnym, spojnym kluczem"
        }
      ]
    },
    "priceGrosz": {
      "type": "integer",
      "unit": "grosz",
      "hasRequiredTextFormat": false,
      "allowedRange": {
        "min": 0,
        "minInclusive": true,
        "max": "Number.MAX_SAFE_INTEGER",
        "maxInclusive": true
      },
      "equivalenceClasses": [
        {
          "name": "ujemna",
          "valid": false,
          "probes": [
            -1,
            -100
          ],
          "probes@expr": [
            "-0"
          ],
          "raises": "RangeError",
          "note": "-0: Number.isInteger(-0) jest true, a -0 < 0 jest false, wiec -0 PRZECHODZI walidacje (klasa `zero`)"
        },
        {
          "name": "nie-calkowita",
          "valid": false,
          "probes": [
            0.5,
            1.01,
            99.999
          ],
          "probes@expr": [
            "NaN",
            "Infinity",
            "-Infinity"
          ],
          "raises": "RangeError"
        },
        {
          "name": "zero",
          "valid": true,
          "probes": [
            0
          ],
          "probes@expr": [
            "-0"
          ]
        },
        {
          "name": "typowa",
          "valid": true,
          "probes": [
            1,
            99,
            100,
            1000,
            1999,
            12345
          ]
        },
        {
          "name": "skrajnie-duza",
          "valid": true,
          "probes@expr": [
            "Number.MAX_SAFE_INTEGER"
          ],
          "note": "przy duzych cenach i ilosciach `priceGrosz * qty` przekracza zakres bezpiecznych liczb calkowitych - patrz DIV-CART-4"
