{
  "f": "Cart.applyCoupon",
  "rules": [
    {
      "id": "CART-COUPON-R1",
      "rule": "Kupon ustawia rabat procentowy dla calego koszyka: \"SAVE10\" daje 10%, \"HALF\" daje 50%. Nie ma innych kodow.",
      "boundaries": [
        {
          "sequence": [
            {
              "call": "add",
              "args": {
                "sku": "SKU-1",
                "priceGrosz": 1000,
                "qty": 2
              }
            },
            {
              "call": "applyCoupon",
              "args": {
                "code": "SAVE10"
              }
            },
            {
              "call": "total",
              "expectedPerSpec": 1800
            }
          ],
          "note": "2000 gr - 10%"
        },
        {
          "sequence": [
            {
              "call": "add",
              "args": {
                "sku": "SKU-1",
                "priceGrosz": 1000,
                "qty": 2
              }
            },
            {
              "call": "applyCoupon",
              "args": {
                "code": "HALF"
              }
            },
            {
              "call": "total",
              "expectedPerSpec": 1000
            }
          ],
          "note": "2000 gr - 50%"
        },
        {
          "sequence": [
            {
              "call": "add",
              "args": {
                "sku": "SKU-1",
                "priceGrosz": 1000,
                "qty": 2
              }
            },
            {
              "call": "applyCoupon",
              "args": {
                "code": "save10"
              },
              "raises": "Error: unknown coupon"
            }
          ],
          "note": "kody sa case-sensitive"
        }
      ]
    },
    {
      "id": "CART-COUPON-R2",
      "rule": "Nieznany kod kuponu konczy sie bledem `Error: unknown coupon` i NIE zmienia obowiazujacego rabatu.",
      "boundaries": [
        {
          "sequence": [
            {
              "call": "add",
              "args": {
                "sku": "SKU-1",
                "priceGrosz": 1000,
                "qty": 2
              }
            },
            {
              "call": "applyCoupon",
              "args": {
                "code": "HALF"
              }
            },
            {
              "call": "applyCoupon",
              "args": {
                "code": "NIE-ISTNIEJE"
              },
              "raises": "Error: unknown coupon"
            },
            {
              "call": "total",
              "expectedPerSpec": 1000
            }
          ],
          "note": "odrzucony kupon nie kasuje wczesniejszego rabatu 50%"
        },
        {
          "sequence": [
            {
              "call": "add",
              "args": {
                "sku": "SKU-1",
                "priceGrosz": 1000,
                "qty": 2
              }
            },
            {
              "call": "applyCoupon",
              "args": {
                "code": "constructor"
              },
              "expectedPerSpec": "Error: unknown coupon",
              "currentCodeBehavior": "brak bledu - discountPct staje sie funkcja Object"
            },
            {
              "call": "total",
              "expectedPerSpec": 2000,
              "currentCodeBehavior": "NaN"
            }
          ],
          "note": "KLUCZOWA GRANICA: klucze z prototypu Object. Patrz DIV-CART-5."
        }
      ]
    },
    {
      "id": "CART-COUPON-R3",
      "rule": "Kuponu nie mozna zastosowac do pustego koszyka - `Error: cannot apply coupon to an empty cart`.",
      "boundaries": [
        {
          "sequence": [
            {
              "call": "applyCoupon",
              "args": {
                "code": "SAVE10"
              },
              "raises": "Error: cannot apply coupon to an empty cart"
            }
          ],
          "note": "swiezy koszyk"
        },
        {
          "sequence": [
            {
              "call": "applyCoupon",
              "args": {
                "code": "NIE-ISTNIEJE"
              },
              "expectedPerSpec": "Error: unknown coupon",
              "currentCodeBehavior": "Error: unknown coupon"
            }
          ],
          "note": "GRANICA KOLEJNOSCI: pusty koszyk ORAZ nieznany kod. Kod sprawdza kod kuponu przed pustoscia (src/cart.ts:50-56). SPEC podaje oba warunki w jednej tabeli bez kolejnosci - nie nalezy na tym opierac oracle, patrz DIV-CART-6."
        },
        {
          "sequence": [
            {
