const fs=require('fs');
const parser=require('@babel/parser');
const src=fs.readFileSync('seeds/semantic-seeds.js','utf8');
const ast=parser.parse(src,{sourceType:'script'});
const strings=new Set(), numbers=new Set();
let tmpl=0, regex=0;
(function walk(n){
  if(!n||typeof n!=='object')return;
  if(Array.isArray(n))return n.forEach(walk);
  if(n.type==='StringLiteral')strings.add(n.value);
  if(n.type==='NumericLiteral')numbers.add(n.value);
  if(n.type==='TemplateLiteral')tmpl++;
  if(n.type==='RegExpLiteral')regex++;
  for(const k in n){if(k!=='loc'&&k!=='leadingComments'&&k!=='trailingComments'&&k!=='innerComments')walk(n[k]);}
})(ast.program);
console.log('unique string literals:',strings.size);
console.log('unique numeric literals:',numbers.size);
console.log('template literals:',tmpl,' regex literals:',regex);
const must=['FV/2026/09/0042','FV/2000/01/0001','FV/2100/12/9999','FV/1999/12/0001','FV/2101/01/0001','FV/2026/09/0000','FV/2026/13/0001','SAVE10','HALF','constructor','__proto__','SKU-1','SKU-2','sku-1','SKU-1 ','PL','EU','WORLD','pl','PL ','🇵🇱'];
const missS=must.filter(v=>!strings.has(v));
console.log('missing required strings:',missS.length?missS:'NONE');
const mustN=[5000,4999.99,5000.01,10,30,100,10.0001,30.0001,100.0001,0.8,35,15,25,45,50000,50010,25000,1999,1995,3,5,1,0,9007199254740991,5e-324];
const missN=mustN.filter(v=>!numbers.has(v));
console.log('missing required numbers:',missN.length?missN:'NONE');
console.log('has -0 as literal 0:',numbers.has(0));
EOF
